	private static List<String> sorted(List<String> rows) {
		List<String> copy = new ArrayList<>(rows);
		copy.sort(String::compareTo);
		return copy;
	}

	private List<String> rows(String query) {
		List<String> rendered = new ArrayList<>();
		try (SailRepositoryConnection conn = repository.getConnection()) {
			try (var result = conn.prepareTupleQuery(query).evaluate()) {
				while (result.hasNext()) {
					var bindings = result.next();
					List<String> parts = new ArrayList<>();
					for (String name : bindings.getBindingNames()) {
						parts.add(name + "=" + bindings.getValue(name));
					}
					parts.sort(String::compareTo);
					rendered.add(String.join("|", parts));
				}
			}
		}
		return rendered;
	}

	private String explanation(String query) {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			return connection.prepareTupleQuery(query).explain(Explanation.Level.Telemetry).toString();
		}
	}

	@Test
	public void everyPartitionIsDisjointFromTheOthers() throws Exception {
		try (SailDataset dataset = openDataset()) {
			NativeLmdbQuerySource source = (NativeLmdbQuerySource) dataset;
			long predicate = source.idOf(repository.getValueFactory().createIRI(EX, "p"));
			Kernel ir = new Kernel(2,
					List.of(new ScanQuad(0, new Operand[] { null, Operand.constant(0), null, null },
							new int[] { 0, -1, 1, -1 })),
					new Emit(new int[] { 0, 1 }, false, OutputMods.none()));

			LmdbRootScanPartition[] partitions = source.planRootScanPartitions(-1L, predicate, -1L, -1L, 4);
			assertNotNull(partitions);
			Set<String> seen = new HashSet<>();
			for (LmdbRootScanPartition partition : partitions) {
				for (long[] row : runOn(source, ir, new long[] { predicate }, partition)) {
					assertTrue(seen.add(Arrays.toString(row)),
							"row " + Arrays.toString(row) + " was produced by more than one partition");
				}
			}
			assertEquals(STATEMENTS, seen.size());
		}
	}

	private SailDataset openDataset() {
		return NativeQuerySourceAccess.openExplicitDataset((LmdbStore) repository.getSail());
	}

	/** Runs the kernel, optionally confining its single scan site to one planned partition. */
	private static List<long[]> runOn(NativeLmdbQuerySource source, Kernel ir, long[] constants,
			LmdbRootScanPartition partition) throws Exception {
		JaninoKernel kernel = LmdbNativeJaninoCodegen.kernel(ir.shapeKey(), ir.className(),
				() -> LmdbNativeKernelEmitter.emit(ir), Long.MAX_VALUE);
		if (kernel == null) {
			kernel = LmdbNativeJaninoCodegen.awaitKernel(ir.shapeKey(), 30, TimeUnit.SECONDS);
		}
		assertNotNull(kernel, "kernel did not compile");
		LmdbNativeKernelScanner scanner = new LmdbNativeKernelScanner(source,
				new StatementOrder[ir.requirements.scans]);
		try {
			if (partition != null) {
				scanner.restrictRootScan(0, partition);
			}
			kernel.bind(new KernelContext(new NativeLmdbQuerySource.NativeAdjacency[0], constants, new long[0],
					new long[0][], null, scanner));
			int stride = ir.stride();
			int maxRows = 256;
			long[] buffer = new long[stride * maxRows];
			List<long[]> rows = new ArrayList<>();
			int filled;
			while ((filled = kernel.fill(buffer, maxRows)) > 0) {
				for (int r = 0; r < filled; r++) {
					rows.add(Arrays.copyOfRange(buffer, r * stride, (r + 1) * stride));
				}
			}
			return rows;
		} finally {
			kernel.close();
			scanner.close();
		}
	}

	private static List<String> render(List<long[]> rows) {
		List<String> rendered = new ArrayList<>(rows.size());
		for (long[] row : rows) {
			rendered.add(Arrays.toString(row));
		}
		rendered.sort(String::compareTo);
		return rendered;
	}
